H.background();
const a = P.a; // leg a
const b = P.b; // leg b
const c = Math.sqrt(a * a + b * b);
// Right angle at origin O. Scale so squares fit.
const maxSide = Math.max(a, b, 1);
const s = 150 / maxSide; // px per unit
const Ox = H.W * 0.42, Oy = H.H * 0.66; // right-angle corner
// place leg a horizontal (to the right), leg b vertical (up)
const Px = Ox + a * s, Py = Oy;       // end of leg a
const Qx = Ox, Qy = Oy - b * s;       // end of leg b
// triangle
H.path([[Ox,Oy],[Px,Py],[Qx,Qy]], { color: H.colors.ink, width: 3, close: true });
// right-angle marker
const m = 12;
H.path([[Ox+m,Oy],[Ox+m,Oy-m],[Ox,Oy-m]], { color: H.colors.sub, width: 1.5 });
// square on leg a (below the horizontal leg)
H.path([[Ox,Oy],[Px,Py],[Px,Py + a*s],[Ox,Oy + a*s]], { color: H.colors.accent, width: 2, fill: "rgba(124,196,255,0.18)", close: true });
// square on leg b (to the left of vertical leg)
H.path([[Ox,Oy],[Qx,Qy],[Qx - b*s,Qy],[Ox - b*s,Oy]], { color: H.colors.accent2, width: 2, fill: "rgba(244,162,89,0.18)", close: true });
// square on hypotenuse: outward normal
const hx = Qx - Px, hy = Qy - Py; // vector P->Q (hypotenuse)
const len = Math.sqrt(hx*hx + hy*hy) || 1;
// outward normal (rotate hypotenuse vector -90 to push away from triangle)
const nx = hy / len, ny = -hx / len;
const H1x = Px + nx * c * s, H1y = Py + ny * c * s;
const H2x = Qx + nx * c * s, H2y = Qy + ny * c * s;
H.path([[Px,Py],[Qx,Qy],[H2x,H2y],[H1x,H1y]], { color: H.colors.good, width: 2, fill: "rgba(103,232,176,0.18)", close: true });
// animated pulse dot traveling along hypotenuse
const u = (Math.sin(t * 0.9) * 0.5 + 0.5);
const dx = Px + (Qx - Px) * u, dy = Py + (Qy - Py) * u;
H.circle(dx, dy, 6, { fill: H.colors.warn });
// labels
H.text("a²", (Ox + Px)/2 - 8, Oy + a*s*0.55, { color: H.colors.accent, size: 13 });
H.text("b²", Ox - b*s*0.55 - 6, (Oy + Qy)/2, { color: H.colors.accent2, size: 13 });
H.text("c²", (H1x + H2x)/2 - 8, (H1y + H2y)/2, { color: H.colors.good, size: 13 });
H.text("a = " + a.toFixed(1), (Ox+Px)/2 - 14, Oy - 8, { color: H.colors.sub, size: 12 });
H.text("b = " + b.toFixed(1), Ox + 6, (Oy+Qy)/2, { color: H.colors.sub, size: 12 });
// title
H.text("Pythagorean theorem: a² + b² = c²", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("the two leg squares' areas add up to the hypotenuse square", 24, 52, { color: H.colors.sub, size: 13 });
H.text("c = √(" + (a*a).toFixed(1) + " + " + (b*b).toFixed(1) + ") = " + c.toFixed(2), 24, 76, { color: H.colors.good, size: 13 });
